const DEFAULT_SETTINGS = { fov: 105, sensitivity: 1, brightness: 0.96, volume: 0.5, musicVolume: 0.25, waveVolume: 0.15, sfxVolume: 0.15, walkSpeed: 1.0, invertY: false, devMode: false, sv: 3 };   // the owner's own, Sep 27 2026
