  const lights = new THREE.Points(lg, new THREE.PointsMaterial({
    color: 0xd9a066, size: 1.5, sizeAttenuation: true, transparent: true, opacity: 0.34, depthWrite: false, fog: false,
  }));
  lights.frustumCulled = false;
