window.addEventListener('keydown', (e) => {
  if (introStarted) return;
  if (e.code === 'Enter' || e.code === 'Space' || e.code === 'NumpadEnter') beginGame();
});
overlay.querySelector('.start').addEventListener('click', (e) => { e.stopPropagation(); beginGame(); });
