  for (let k = 0; k < n1; k++) spos.push(pos[k * 3] - nrm[k * 3] * T * 0.5, pos[k * 3 + 1] - nrm[k * 3 + 1] * T * 0.5, pos[k * 3 + 2] - nrm[k * 3 + 2] * T * 0.5);
