  const bp = ctx.createBiquadFilter(); bp.type = 'bandpass';
  bp.frequency.setValueAtTime(320, t);
  bp.frequency.exponentialRampToValueAtTime(760, t + 0.5);
  bp.Q.value = 2.2;
