  cg.gain.setValueAtTime(0.0001, t);
  cg.gain.exponentialRampToValueAtTime(0.28, t + 0.12);
  cg.gain.exponentialRampToValueAtTime(0.0001, t + 1.1);
  creak.connect(cf).connect(cg).connect(out);
  creak.start(t); creak.stop(t + 1.1);

