  let d = Math.hypot(dx, dz);
  const ang = Math.atan2(dx, dz);
  const feet = camBaseY - playerEye();
  const clampTo = (r) => { if (d > 0.001) { camera.position.x = MUSH_X + (dx / d) * r; camera.position.z = MUSH_Z + (dz / d) * r; d = r; } };
