const MUT_HIT_STOP = 0.09;
const MUT_HEAVY = 0.85;                    // a swing wound past this takes two
const MUT_STRAFE = 1.7;                    // how fast they circle you at reach
const MUT_SEP = 2.6;                       // and how far off each other they stay
