  lp.type = th === 'chitter' ? 'bandpass' : 'lowpass';
  lp.frequency.setValueAtTime((th === 'chitter' ? 1500 : 340) * V.f, t);
  lp.frequency.exponentialRampToValueAtTime((th === 'chitter' ? 3200 : 700) * V.f, t + D * 0.5);
  if (th === 'chitter') lp.Q.value = 3.2;
