    sg.gain.setValueAtTime(0.0001, t);
    sg.gain.exponentialRampToValueAtTime(gain * 0.9, t + atk);
    sg.gain.exponentialRampToValueAtTime(0.0001, t + D * 1.1);
    sub.connect(sg).connect(out); sub.start(t); sub.stop(t + D * 1.15);
