  const g = ctx.createGain();
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(0.24, t + D * 0.8);
  g.gain.exponentialRampToValueAtTime(0.0001, t + D + 0.5);
  o.connect(g).connect(out); o.start(t); o.stop(t + D + 0.6);
