  const air = noiseBurst(D, (x) => (0.2 + 0.8 * Math.random()) * Math.pow(x, 1.6));
  const af = ctx.createBiquadFilter(); af.type = 'lowpass';
  af.frequency.setValueAtTime(120, t);
