  g.position.set(x, y, z);
  g.rotation.y = yaw;
  scene.add(g);
  g.updateMatrixWorld(true);
  const b = { group: g, inv: g.matrixWorld.clone().invert(), hidden: !!(opts && opts.hidden) };
  bunkers.push(b);
