  camera.position.set(hatchReturn.x, playerEye(), hatchReturn.z);
  const rc = rockGroundAt(hatchReturn.x, hatchReturn.z, 0);
  groundY = rc ? rc.top : 0;
  camera.position.y = playerEye() + groundY;
  camBaseY = camera.position.y; vy = 0; onGround = true;
