      y -= v.fall * (1 - 0.35 * Math.min(1, A.gust)) * dt;
      x += (wx * 1.6 + Math.sin(t * 1.3 + v.ph) * 0.6) * v.k * dt;
      z += (wz * 1.6 + Math.cos(t * 1.1 + v.ph * 1.7) * 0.6) * v.k * dt;
      y += Math.sin(t * 2.1 + v.ph) * 0.25 * A.gust * dt;
