    // the black holds until the room is down, the cave-in's own rule
    if (catReturn && !catReady) { catT = CAT_OUT + 0.05; return; }
    catCutDone = true;
    if (catReturn) placeInsideCatDoor(); else placeOutsideCatDoor();
