  const B = { x0: CAT_DOOR.x - 0.15, x1: CAT_DOOR.x + 0.85, y0: CAT_DOOR.f + 0.05, y1: CAT_DOOR.f + 3.7,
              z0: CAT_DOOR.z - 1.9, z1: CAT_DOOR.z + 1.9 };
