    if (n >= WH_GL_MAX) break;
    _whGlV.copy(m.L.position).applyMatrix4(Gm).applyMatrix4(V);
    WH_GL.uWhLp.value[n].set(_whGlV.x, _whGlV.y, _whGlV.z, m.L.intensity * 5.5);
    WH_GL.uWhLc.value[n].set(0.62, 0.72, 1.0, 32);
