    const j = Math.round(NT * (0.5 + (rnd() - 0.5) * 0.34));                // high in the vault
    const o = i * NT + j, x = gp.getX(o), y = gp.getY(o), z = gp.getZ(o);
    const fl = whFloor(x, s), len = Math.min(y - fl - 2.6, 1.2 + rnd() * 5.5);
