  const t = whaleT, D = WH_OUT + WH_HOLD + WH_IN;
  const black = t < WH_OUT ? smooth01(0.04, WH_OUT, t) : t < WH_OUT + WH_HOLD ? 1 : 1 - smooth01(WH_OUT + WH_HOLD, D, t);
