  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.setValueAtTime(900, t); lp.frequency.exponentialRampToValueAtTime(220, t + 0.18);
  const g = ctx.createGain(); g.gain.value = 0.34 * (0.8 + Math.random() * 0.4);
