/* ANYTHING THAT KNOWS ONE GROUND IS BROKEN THE DAY THE GAME ACQUIRES A
 * SECOND ONE — the physics bodies, the gibs and the blood have each learned
 * this once already, and the hall six hundred metres over the beach is a
 * third ground. `bunkerFloorAt` is the one door they all ask, so the saucer
 * answers through it rather than adding a fourth code path. */
const _floorBeforeShrine = bunkerFloorAt;
bunkerFloorAt = (x, z, y) => {
  const s = shrineFloorAt(x, z, y);
  return s === null ? _floorBeforeShrine(x, z, y) : s;
};

/* AND HER HOLD IS A GROUND TOO — the fourth, and the same lesson again.
 * Everything loose asks `bunkerFloorAt` what is under it, and inside her
 * the honest answer is her sole at HOLD_Y and not the beach 25 cm below
 * it: without this the boards off the barricade fall THROUGH her floor and
 * lie under it on the sand, and `submersionAt` — which is asked only when
 * this returns null — decides a piece in her hold is floating in the sea,
 * because the swash at her station reaches x = 6.5 and she is at 6.
 * Chained last so it sits on top of the beach, the bunker and the hall,
 * and it answers only between her sole and her deck. */
const _floorBeforeShip = bunkerFloorAt;
bunkerFloorAt = (x, z, y) => {
  const lx = x - SHIP_X, lz = z - SHIP_Z;
  if (y !== undefined && lx > SN.HOLD_X0 && lx < SN.HOLD_X1 && Math.abs(lz) < SN.HOLD_HZ
      && y > SN.HOLD_Y - 0.5 && y < SN.DECK_Y) return SN.HOLD_Y;
  return _floorBeforeShip(x, z, y);
};

/* EVERYTHING THE SAUCER NEEDS, FETCHED AND WARMED UNDER THE TITLE CARD. This
 * is at the bottom of the module for the reason the checkpoint restore is:
 * it names `loadShrine`, which names `SH`, `shrineLights` and `makeShrineBoss`,
 * all declared thousands of lines above but only initialised as the module
 * runs. The fetch is async so it costs nothing here; the parse lands a second
 * or two later, the warm goes on the chain in `animate()` behind the card, and
 * by the time anybody has walked back past the tunnel there is nothing left to

 * pay for. It used to all happen on approach and you could feel every bit. */
loadShrine();
loadUfo();

/* PICKING SOMETHING UP HITCHED FOR ITS ICON. `itemIcon` renders the item's
 * own model into a tile the first time the pack draws it, and that render is
 * 11 to 43 ms (60 for the first, which also compiles the icon target's four
 * programs) — on the frame you take it, which is the frame you are looking at
 * the thing. Every named item is rendered ahead of time instead, one a step
 * on the warm chain behind the title card; a scan that has not landed yet is
 * put back on the chain and asked again later, so nothing is left for the
 * pickup to pay for. */
{
  const want = [cdItem, crabItem, syringeItem, waterBottleItem, glowstickItem, shovelItem,
    militaryItem, katanaItem, bloodItem, ringItem, weddingItem, keyItem, boatKeyItem, skullKeyItem,
    headItem, magnumItem, spliffItem, grammyItem].filter(Boolean);
  const tries = new Map();
  const one = (it) => () => {
    if (it._icon) return;
    try { const c = localStorage.getItem(iconCacheKey(it)); if (c) { it._icon = c; return; } } catch (e) {}   // kept from last time: no render needed
    /* THE PROGRAMS FIRST, THE PICTURE A FRAME LATER. The icon rig has its own
     * lights, so every item compiles its own programs on its first icon —
     * measured, one icon step was a 210 ms frame. They are handed to the
     * driver here and the chain waits on them; the render is queued behind. */
    const model = it.iconModel || it.inspectModel;
    if (model && !it._iconCompiled && renderer.compileAsync) {
      if (iconDrawable(model)) {
        it._iconCompiled = true;
        initIconRig();
        const c = model.clone(true);
        c.traverse((o) => { if (!o.userData.bwKeepHidden) o.visible = true; });
        iconFit.add(c);
        let done = false;
        try { renderer.compileAsync(iconScene, iconCam).then(() => { done = true; }, () => { done = true; }); } catch (e) { done = true; }
        iconFit.remove(c);
        warmHoldFor(() => done);
        /* AND THE TEXTURES A STEP OR TWO AT A TIME: a scan that has not been
         * drawn yet uploads every map it has on its first render, and the
         * wedding ring's sixteen 2048s were the 213 ms left once the programs
         * were out of the way. */
        const maps = new Set();
        model.traverse((o) => { if (!o.isMesh) return; for (const mt of [].concat(o.material)) for (const k in mt) { const v = mt[k]; if (v && v.isTexture) maps.add(v); } });
        const list = [...maps];
        for (let i = 0; i < list.length; i += 2) warmStep('icon tex', () => { for (const t of list.slice(i, i + 2)) { try { renderer.initTexture(t); } catch (e) { /* never fatal */ } } });
        warmStep('icon', one(it));
        return;
      }
    }
    const u = itemIcon(it);
    const n = (tries.get(it) || 0) + 1; tries.set(it, n);
    if (!u && n < 40) setTimeout(() => warmStep('icon', one(it)), 1500);
  };
  for (const it of want) warmStep('icon', one(it));
}
/* AND TAKING THE GLOWSTICK HITCHED FOR ITS VIEW MODEL. The hand's scene has
 * its own lights, so everything drawn in it compiles its own programs, and a
 * tool nobody has held yet compiles them on the frame it comes into your
 * hand: measured on the glowstick, four programs on that frame (20 ms here,
 * several times that on a slower machine). Everything already hung on the
 * mount is compiled here, behind the title, with the hand's own lights. */
warmStep('view models', () => {
  const was = [];
  vmScene.traverse((o) => { was.push([o, o.visible]); o.visible = true; });
  try { renderer.compile(vmScene, vmCamera); } finally { for (const [o, v] of was) o.visible = v; }
});

